import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { Prisma } from "@prisma/client";
import { cacheQuery } from "@/lib/cache";
import { withCache } from "@/lib/simple-cache";

type PrismaRecord = Record<string, unknown>;
type PackagingSettingsRow = { categoryHsnJson?: string | null };
type PackagingSettingsDelegate = { findFirst: (args?: PrismaRecord) => Promise<PackagingSettingsRow | null> };
type PackagingPrismaClient = typeof prisma & { gpisSettings: PackagingSettingsDelegate };
const packagingPrisma = prisma as unknown as PackagingPrismaClient;

function parseCategoryHsnJson(input: unknown): Record<string, string> {
  if (typeof input !== "string" || !input.trim()) return {};
  try {
    const parsed = JSON.parse(input) as unknown;
    if (!parsed || typeof parsed !== "object") return {};
    const out: Record<string, string> = {};
    for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof k !== "string") continue;
      if (typeof v !== "string") continue;
      const key = k.trim();
      const val = v.trim();
      if (!key || !val) continue;
      out[key] = val;
    }
    return out;
  } catch {
    return {};
  }
}

const toNumber = (value: string | null) => {
  if (!value) return undefined;
  const n = Number(value);
  return Number.isFinite(n) ? n : undefined;
};

const toDate = (value: string | null) => {
  if (!value) return undefined;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? undefined : d;
};

export async function GET(request: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const sp = request.nextUrl.searchParams;
  const q = (sp.get("q") || sp.get("query") || "").trim();
  const status = (sp.get("status") || "").trim();
  const weightRange = (sp.get("weightRange") || "").trim();
  const mode = (sp.get("mode") || "full").trim().toLowerCase();

  const minPrice = toNumber(sp.get("minPrice"));
  const maxPrice = toNumber(sp.get("maxPrice"));
  const createdFrom = toDate(sp.get("createdFrom"));
  const createdTo = toDate(sp.get("createdTo"));

  const parseMulti = (key: string) =>
    (sp.get(key) || "")
      .split(",")
      .map((v) => v.trim())
      .filter(Boolean);

  const where: Prisma.InventoryWhereInput = {};

  if (status) where.status = status;

  const categories = parseMulti("category");
  if (categories.length > 0) where.category = { in: categories };

  const gemTypes = parseMulti("gemType");
  if (gemTypes.length > 0) where.gemType = { in: gemTypes };

  const colors = parseMulti("color");
  if (colors.length > 0) where.color = { in: colors };

  const vendorIds = parseMulti("vendorId");
  if (vendorIds.length > 0) where.vendorId = { in: vendorIds };

  if (weightRange) {
    const [min, max] = weightRange.split("-");
    const minN = Number(min);
    if (Number.isFinite(minN)) {
      if (max === "plus") {
        where.weightValue = { gte: minN };
      } else {
        const maxN = Number(max);
        if (Number.isFinite(maxN)) where.weightValue = { gte: minN, lte: maxN };
      }
    }
  }

  if (minPrice !== undefined || maxPrice !== undefined) {
    where.sellingPrice = {
      gte: minPrice,
      lte: maxPrice,
    };
  }

  if (createdFrom || createdTo) {
    where.createdAt = {
      gte: createdFrom,
      lte: createdTo,
    };
  }

  if (q) {
    const or = [
      { sku: { contains: q } },
      { itemName: { contains: q } },
      { internalName: { contains: q } },
      { category: { contains: q } },
      { gemType: { contains: q } },
      { color: { contains: q } },
      { dimensionsMm: { contains: q } },
      { standardSize: { contains: q } },
      { certificateNo: { contains: q } },
      { certificateNumber: { contains: q } },
      { notes: { contains: q } },
      { beadSizeLabel: { contains: q } } as unknown as Prisma.InventoryWhereInput,
    ] as Prisma.InventoryWhereInput[];
    (where as unknown as { OR?: Prisma.InventoryWhereInput[] }).OR = or;
  }

  // const now = new Date();

  const overallWhere: Prisma.InventoryWhereInput = { ...where };
  delete (overallWhere as unknown as { status?: string }).status;

  const imagesWhere = {
    ...where,
    OR: [
      { imageUrl: { not: null } },
      { media: { some: {} } },
    ],
  } as unknown as Prisma.InventoryWhereInput;

  const certificateWhere = {
    ...where,
    AND: [
      {
        OR: [
          { NOT: { OR: [{ certificateNo: null }, { certificateNo: "" }] } },
          { NOT: { OR: [{ certificateNumber: null }, { certificateNumber: "" }] } },
        ],
      },
    ],
  } as unknown as Prisma.InventoryWhereInput;

  const missingCertificationWhere = {
    ...imagesWhere,
    status: "IN_STOCK",
    AND: [
      { OR: [{ certificateNo: null }, { certificateNo: "" }] },
      { OR: [{ certificateNumber: null }, { certificateNumber: "" }] },
    ],
  } as unknown as Prisma.InventoryWhereInput;

  const missingImagesWhere = {
    ...where,
    status: "IN_STOCK",
    imageUrl: null,
    media: { none: {} },
  } as unknown as Prisma.InventoryWhereInput;

  const categoryHsnMap = await withCache("gpis:categoryHsn", 300_000, async () => {
    const raw = (await packagingPrisma.gpisSettings.findFirst())?.categoryHsnJson ?? null;
    return parseCategoryHsnJson(raw);
  });
  const mappedCategories = Object.keys(categoryHsnMap).filter(Boolean);

  const hsnFieldWhere = {
    ...where,
    AND: [
      { hsnCode: { not: null } },
      { hsnCode: { not: "" } },
    ],
  } satisfies Prisma.InventoryWhereInput;

  const hsnMappedWhere = mappedCategories.length
    ? ({ ...where, category: { in: mappedCategories } } satisfies Prisma.InventoryWhereInput)
    : ({ ...where, id: { equals: "__NO_MATCH__" } } satisfies Prisma.InventoryWhereInput);

  const hsnReadyWhere = mappedCategories.length
    ? ({
        ...where,
        OR: [hsnFieldWhere, hsnMappedWhere],
      } as unknown as Prisma.InventoryWhereInput)
    : hsnFieldWhere;

  const completenessWhere = {
    AND: [
      imagesWhere,
      certificateWhere,
      hsnReadyWhere,
    ],
  } as unknown as Prisma.InventoryWhereInput;

  const cacheKey = JSON.stringify({ q, categories, gemTypes, colors, status, vendorIds, weightRange, minPrice, maxPrice, createdFrom: createdFrom?.toISOString(), createdTo: createdTo?.toISOString(), mode });

  const getQuick = cacheQuery(
    async () => {
      const [totalItems, sums, withImagesCount, withCertificateCount, missingCertificationCount, missingImagesCount, withHsnCount, completenessAllCount, overallTotalItems, agingDead, agingFresh, agingSlow] = await Promise.all([
        prisma.inventory.count({ where }),
        prisma.inventory.aggregate({ where, _sum: { sellingPrice: true }, _avg: { sellingPrice: true }, _max: { sellingPrice: true } }),
        prisma.inventory.count({ where: imagesWhere }),
        prisma.inventory.count({ where: certificateWhere }),
        prisma.inventory.count({ where: missingCertificationWhere }),
        prisma.inventory.count({ where: missingImagesWhere }),
        prisma.inventory.count({ where: hsnReadyWhere }),
        prisma.inventory.count({ where: completenessWhere }),
        prisma.inventory.count({ where: overallWhere }),
        prisma.inventory.count({
          where: { ...where, status: "IN_STOCK", hideFromAttention: false, createdAt: { lt: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000) } },
        }),
        prisma.inventory.count({
          where: { ...where, status: "IN_STOCK", hideFromAttention: false, createdAt: { gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) } },
        }),
        prisma.inventory.count({
          where: {
            ...where, status: "IN_STOCK", hideFromAttention: false,
            createdAt: { lt: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), gte: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000) },
          },
        }),
      ]);

      return {
        totalItems,
        overallTotalItems,
        totalSell: Number(sums?._sum?.sellingPrice || 0),
        avgSell: Number(sums?._avg?.sellingPrice || 0),
        maxSell: Number(sums?._max?.sellingPrice || 0),
        withImagesCount,
        withCertificateCount,
        missingCertificationCount,
        missingImagesCount,
        withHsnCount,
        completenessAllCount,
        aging: { fresh: agingFresh, slow: agingSlow, dead: agingDead },
      };
    },
    ["inventory", "stats", "quick", cacheKey],
    30,
    ["inventory:stats"]
  );

  const getFull = cacheQuery(
    async () => {
      const [
        totalItems,
        sums,
        byCategory,
        byGemType,
        byCategoryGemType,
        byStatus,
        withImagesCount,
        withCertificateCount,
        missingCertificationCount,
        missingImagesCount,
        withHsnCount,
        completenessAllCount,
        overallTotalItems,
        overallByStatus,
        agingFresh,
        agingSlow,
        agingDead,
      ] = await Promise.all([
        prisma.inventory.count({ where }),
        prisma.inventory.aggregate({ where, _sum: { sellingPrice: true }, _avg: { sellingPrice: true }, _max: { sellingPrice: true } }),
        prisma.inventory.groupBy({
          by: ["category", "status"],
          where,
          _count: { id: true },
          _sum: { sellingPrice: true },
          orderBy: { _count: { id: "desc" } },
        }),
        prisma.inventory.groupBy({
          by: ["gemType", "status"],
          where,
          _count: { id: true },
          _sum: { sellingPrice: true },
          orderBy: { _count: { id: "desc" } },
        }),
        prisma.inventory.groupBy({
          by: ["category", "gemType", "status"],
          where,
          _count: { id: true },
          _sum: { sellingPrice: true },
        }),
        prisma.inventory.groupBy({
          by: ["status"],
          where,
          _count: { id: true },
          orderBy: { _count: { id: "desc" } },
        }),
        prisma.inventory.count({ where: imagesWhere }),
        prisma.inventory.count({ where: certificateWhere }),
        prisma.inventory.count({ where: missingCertificationWhere }),
        prisma.inventory.count({ where: missingImagesWhere }),
        prisma.inventory.count({ where: hsnReadyWhere }),
        prisma.inventory.count({ where: completenessWhere }),
        prisma.inventory.count({ where: overallWhere }),
        prisma.inventory.groupBy({
          by: ["status"],
          where: overallWhere,
          _count: { id: true },
          orderBy: { _count: { id: "desc" } },
        }),
        prisma.inventory.count({
          where: {
            ...where,
            status: "IN_STOCK",
            hideFromAttention: false,
            createdAt: { gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) },
          },
        }),
        prisma.inventory.count({
          where: {
            ...where,
            status: "IN_STOCK",
            hideFromAttention: false,
            createdAt: {
              lt: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000),
              gte: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000),
            },
          },
        }),
        prisma.inventory.count({
          where: {
            ...where,
            status: "IN_STOCK",
            hideFromAttention: false,
            createdAt: { lt: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000) },
          },
        }),
      ]);

      const totalSell = Number(sums?._sum?.sellingPrice || 0);
      const avgSell = Number(sums?._avg?.sellingPrice || 0);
      const maxSell = Number(sums?._max?.sellingPrice || 0);

      return {
        totalItems,
        overallTotalItems,
        totalSell,
        avgSell,
        maxSell,
        withImagesCount,
        withCertificateCount,
        missingCertificationCount,
        missingImagesCount,
        withHsnCount,
        completenessAllCount,
        aging: { fresh: agingFresh, slow: agingSlow, dead: agingDead },
        byCategory: byCategory.map((r) => ({ category: r.category || "-", status: r.status || "-", items: r._count.id, sellValue: Number(r._sum.sellingPrice || 0) })),
        byGemType: byGemType.map((r) => ({ gemType: r.gemType || "-", status: r.status || "-", items: r._count.id, sellValue: Number(r._sum.sellingPrice || 0) })),
        byCategoryGemType: byCategoryGemType.map((r) => ({ category: r.category || "-", gemType: r.gemType || "-", status: r.status || "-", items: r._count.id, sellValue: Number(r._sum.sellingPrice || 0) })),
        byStatus: byStatus.map((r) => ({ status: r.status || "-", items: r._count.id })),
        overallByStatus: overallByStatus.map((r) => ({ status: r.status || "-", items: r._count.id })),
      };
    },
    ["inventory", "stats", "full", cacheKey],
    60,
    ["inventory:stats"]
  );

  if (mode === "quick") {
    const payload = await getQuick();
    return NextResponse.json(payload);
  }

  const payload = await getFull();
  return NextResponse.json(payload);

  } catch (err) {
    console.error("[inventory/stats] error:", err);
    return NextResponse.json({ error: "Internal error" }, { status: 500 });
  }
}
